<?php
require_once __DIR__.'/../admin.php';if(!admin_can('support')){http_response_code(403);exit('Permission denied.');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$id=sc_support_submit($_POST);header('Location: ./?id='.$id.'&saved=1',true,303);exit;}catch(Throwable $e){$error=$e instanceof mysqli_sql_exception?'Could not save this ticket. Please try again.':$e->getMessage();}}
$id=max(0,(int)($_GET['id']??0));$ticket=$id?sc_support_ticket($id):null;$page=max(1,(int)($_GET['p']??1));$tickets=sc_query('SELECT id,ticketid,title,status,created_at FROM support_tickets WHERE COALESCE(reply_to_id,0)=0 AND is_deleted=0'.sc_support_scope().' ORDER BY id DESC LIMIT 25 OFFSET '.(($page-1)*25))->get_result();admin_console_open('Support');
?>
<p>Track website and operations issues here. Tickets are stored in this application; no external message is sent.</p><?php if($error): ?><p class="alert alert-danger" role="alert"><?= sc_e($error) ?></p><?php endif; ?><?php if(isset($_GET['saved'])): ?><p class="alert alert-success">Ticket saved.</p><?php endif; ?><a class="btn btn-outline-primary mb-3" href="./">Ticket list</a><?php if(admin_can('support','create')): ?> <a class="btn btn-primary mb-3" href="?new_ticket">New ticket</a><?php endif; ?>
<?php if($id&&!$ticket): ?><p>Ticket not found or unavailable for your account.</p><?php elseif($ticket): ?><article class="card p-4 mb-4"><h2 class="h4"><?= sc_e($ticket['title']) ?></h2><p><?= sc_e($ticket['ticketid'].' | '.$ticket['status'].' | '.$ticket['created_at']) ?></p><?php $messages=[$ticket];$replies=sc_query('SELECT * FROM support_tickets WHERE reply_to_id=? AND is_deleted=0 ORDER BY id','i',[$id])->get_result()->fetch_all(MYSQLI_ASSOC);$messages=array_merge($messages,$replies);foreach($messages as $m): ?><section class="border-bottom py-3"><small><?= sc_e($m['created_at']) ?></small><p><?= nl2br(sc_e(strip_tags($m['description']))) ?></p><?php foreach((json_decode($m['attachments'],true)?:[]) as $i=>$file): ?><a class="btn btn-sm btn-outline-secondary" href="download.php?ticket=<?= (int)$m['id'] ?>&file=<?= $i ?>">Attachment <?= $i+1 ?></a><?php endforeach; ?></section><?php endforeach; ?></article><?php if(admin_can('support','update')): ?><div class="card p-4"><form method="post" enctype="multipart/form-data"><?= sc_token() ?><input type="hidden" name="action" value="reply"><input type="hidden" name="ticket_id" value="<?= $id ?>"><label class="d-block mb-3">Reply<textarea class="form-control" name="description" maxlength="10000" required></textarea></label><label class="d-block mb-3">Attachments (up to 3 files, 1 MB each)<input class="form-control" type="file" name="ticket_attachments[]" multiple accept="application/pdf,image/png,image/jpeg,image/webp,image/gif"></label><button class="btn btn-primary">Add reply</button></form><form method="post" class="mt-3"><?= sc_token() ?><input type="hidden" name="ticket_id" value="<?= $id ?>"><button class="btn btn-outline-secondary" name="action" value="<?= $ticket['status']==='Resolved'?'reopen':'resolve' ?>"><?= $ticket['status']==='Resolved'?'Reopen ticket':'Mark resolved' ?></button></form></div><?php endif; ?>
<?php elseif(isset($_GET['new_ticket'])&&admin_can('support','create')): ?><div class="card p-4"><form method="post" enctype="multipart/form-data"><?= sc_token() ?><input type="hidden" name="action" value="create"><label class="d-block mb-3">Issue title<input class="form-control" name="title" maxlength="50" required></label><label class="d-block mb-3">Type<select class="form-select" name="issue_type"><?php foreach(['Technical','Account','Product','Billing','Other'] as $type): ?><option><?= $type ?></option><?php endforeach; ?></select></label><label class="d-block mb-3">Description<textarea class="form-control" name="description" rows="6" maxlength="10000" required></textarea></label><label class="d-block mb-3">Attachments (PDF or images, 1 MB each)<input class="form-control" type="file" name="ticket_attachments[]" multiple accept="application/pdf,image/png,image/jpeg,image/webp,image/gif"></label><button class="btn btn-primary">Create ticket</button></form></div>
<?php else: ?><div class="card p-3"><div class="table-responsive"><table class="table" data-info="ignore-dt"><thead><tr><th>Reference</th><th>Issue</th><th>Status</th><th>Created</th></tr></thead><tbody><?php while($t=$tickets->fetch_assoc()): ?><tr><td><a href="?id=<?= $t['id'] ?>"><?= sc_e($t['ticketid']) ?></a></td><td><?= sc_e($t['title']) ?></td><td><?= sc_e($t['status']) ?></td><td><?= sc_e($t['created_at']) ?></td></tr><?php endwhile; ?></tbody></table></div><nav class="sc-list-pager"><a href="?p=<?= max(1,$page-1) ?>">Previous</a><a href="?p=<?= $page+1 ?>">Next</a></nav></div><?php endif; ?><?php admin_console_close(); ?>
